There's no search input in this directory (it's a config folder, not a project), so here is the vanilla version to drop in; `#search`, `/api/search` and `render` are placeholders for your own names.

```js
const input = document.querySelector('#search');
let timer, controller;

input.addEventListener('input', () => {
  clearTimeout(timer);
  timer = setTimeout(async () => {
    controller?.abort(); // drop the in-flight request so a slow old response can't overwrite a newer one
    controller = new AbortController();
    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(input.value)}`, { signal: controller.signal });
      render(await res.json());
    } catch (e) {
      if (e.name !== 'AbortError') throw e;
    }
  }, 300);
});
```

If it's React, the same thing goes in an effect:

```js
useEffect(() => {
  const controller = new AbortController();
  const timer = setTimeout(() => {
    fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal: controller.signal })
      .then(r => r.json())
      .then(setResults)
      .catch(e => { if (e.name !== 'AbortError') throw e; });
  }, 300);
  return () => { clearTimeout(timer); controller.abort(); };
}, [query]);
```

